mapper.update:
UPDATE payments
SET status = 'CANCELED',
    provider_status = #{providerStatus},
    canceled_at = #{canceledAt}
WHERE id = #{paymentId}
  AND status = 'DONE'

UPDATE payment_cancellations
SET status = 'FAILED',
    failure_code = #{failureCode},
    failure_message = #{failureMessage}
WHERE id = #{cancellationId}
  AND status = 'REQUESTED'
